name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

env:
  POSTGRES_DSN: postgres://postgres:umm-ci@127.0.0.1:5432/umm?sslmode=disable
  BOOTSTRAP_ADMIN: admin
  BOOTSTRAP_ADMIN_PASSWORD: CI-Admin-Password-2026!
  ENCRYPTION_KEY: AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=

jobs:
  verify:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:17-alpine
        env:
          POSTGRES_PASSWORD: umm-ci
          POSTGRES_DB: umm
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U postgres -d umm"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v6
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json

      # --- Version -----------------------------------------------------------
      # Before anything slow: a version that disagrees with itself fails the
      # release workflow at tag time, which is after the merge.
      - name: Version consistency
        run: ./scripts/check-version.sh

      # --- Go ---------------------------------------------------------------
      - run: go vet ./...
      # -p 1 because the integration tests share one PostgreSQL database, and
      # app_settings holds a single global ai_gateway row. Run in parallel, two
      # packages swap that row underneath each other: measured 2 failures in 3
      # runs, 0 in 3 when serialised. The database serialises the slow work
      # anyway, so this costs about 3% of wall time (116s -> 120s).
      - run: go test -p 1 ./...
      # The per-note counts are computed by several goroutines at once and the
      # suite above does not look for races. Nothing else would: two workers
      # writing the same correct number into the same slot produces the right
      # answer every time and a race only the detector can see.
      - name: Race detector on the concurrent paths
        run: go test -race -count=1 ./internal/intelligence
      - name: Go vulnerability scan
        run: go run golang.org/x/vuln/cmd/govulncheck@latest ./...
      # Prints the measured behaviour of the active embedding algorithm and
      # fails if its ability to tell meaning from vocabulary regresses.
      - name: Embedding quality report
        run: go test ./internal/intelligence -run 'Quality|Vocabulary|Threshold|Semantic' -v

      # --- Database ---------------------------------------------------------
      - name: Migration dry run
        env:
          POSTGRES_CONTAINER: ${{ job.services.postgres.id }}
          POSTGRES_USER: postgres
        run: ./scripts/migrate-dry-run.sh
      # The dry run covers an empty schema. This drives migration 010 over real
      # edge data, where a rollback could otherwise lose someone's connections.
      - name: Memory graph migration drill
        env:
          POSTGRES_CONTAINER: ${{ job.services.postgres.id }}
          POSTGRES_USER: postgres
        run: ./scripts/graph-migration-drill.sh
      - name: Build server
        run: go build -ldflags '-X main.version=ci' -o /tmp/umm-ci ./cmd/umm
      - name: PostgreSQL integration smoke
        run: ./scripts/integration-smoke.sh
      - name: Multi-instance smoke
        env:
          UMM_SMOKE_BINARY: /tmp/umm-ci
          POSTGRES_CONTAINER: ${{ job.services.postgres.id }}
          POSTGRES_USER: postgres
        run: ./scripts/multi-instance-smoke.sh
      - name: Store integration regressions
        run: go test ./internal/store -run 'Test.*Integration' -count=1
      - name: HTTP reliability regressions
        env:
          POSTGRES_DSN: postgres://postgres:umm-ci@127.0.0.1:5432/umm?sslmode=disable
        run: go test ./internal/httpapi -run 'Test.*Integration' -count=1
      - name: Webhook persistence regression
        run: go test ./internal/webhook -run 'Test.*Integration' -count=1
      - name: Backup and restore drill
        env:
          POSTGRES_CONTAINER_ID: ${{ job.services.postgres.id }}
          POSTGRES_USER: postgres
          POSTGRES_SOURCE_DB: umm
          RESTORE_TEST_DB: umm_restore_ci
        run: ./scripts/restore-smoke.sh
      - name: Dream inbox database integration
        run: go test ./internal/dream -run TestDreamInboxAcceptanceIntegration -count=1

      # --- Frontend ---------------------------------------------------------
      - run: npm ci
        working-directory: web
      - run: npm run test:offline-queue
        working-directory: web
      - name: Frontend dependency audit
        run: npm audit --audit-level=high
        working-directory: web
      - name: Frontend types
        run: npm run typecheck
        working-directory: web
      - name: Frontend lint and format
        run: npm run lint
        working-directory: web
      - name: Translation coverage
        run: node scripts/check-i18n.mjs
        working-directory: web
      - name: Frontend unit tests
        run: npm test
        working-directory: web
      - name: Build bundle
        run: npm run build
        working-directory: web
      - name: Service worker and offline shell checks
        run: npm run verify:pwa
        working-directory: web

      # --- End to end -------------------------------------------------------
      # Runs against the real binary serving the real bundle, so the offline
      # queue, the language switch and the Content-Security-Policy are exercised
      # the way a browser meets them.
      - name: Install Playwright browser
        run: npx playwright install --with-deps chromium
        working-directory: web
      - name: End-to-end tests
        env:
          UMM_HTTP_ADDR: 127.0.0.1:8085
          UMM_BASE_URL: http://127.0.0.1:8085
          UMM_E2E_COMMAND: /tmp/umm-ci
        run: npx playwright test
        working-directory: web
      - name: Upload end-to-end report
        if: failure()
        uses: actions/upload-artifact@v4
        with:
          name: playwright-report
          path: web/test-results
          retention-days: 7

      # --- Image ------------------------------------------------------------
      - run: docker build --build-arg VERSION=$(tr -d '[:space:]' < VERSION) -t umm:ci .
